package com.inventra.backend.repository; import com.inventra.backend.model.Inventory; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface InventoryRepository extends MongoRepository<Inventory,String> { Optional<Inventory> findByWarehouseIdAndProductId(String warehouseId,String productId); List<Inventory> findByWarehouseId(String warehouseId); List<Inventory> findByProductId(String productId); }
